enum Download {
  case idle
  case running(progress: Double)
  case failed(Error, retryIn: TimeInterval)
}

func describe(_ state: Download) -> String {
  switch state {
  case .idle:
    return "waiting"
  case .running(let p) where p > 0.9:          // where refines the case
    return "almost done"
  case .running(let p):
    return "\(Int(p * 100))%"
  case .failed(let error, let retry):          // bind both payloads
    return "\(error.localizedDescription), retrying in \(retry)s"
  }                                            // no default: exhaustive
}

// Ranges and tuples
func grade(_ score: Int) -> String {
  switch score {
  case ..<50:   return "fail"
  case 50..<80: return "pass"
  default:      return "distinction"
  }
}

func quadrant(_ point: (x: Int, y: Int)) -> String {
  switch point {
  case (0, 0):                 return "origin"
  case (let x, 0) where x > 0: return "positive x axis"
  case (_, let y) where y < 0: return "below"
  default:                     return "elsewhere"
  }
}

