@MainActor
final class FeedViewModel: ObservableObject {
  @Published var isLoading = false
  @Published var items: [Item] = []
  let api: API

  // ❌ every exit path has to remember to reset the flag
  func loadBad() async {
    isLoading = true
    do { items = try await api.feed() } catch { return }   // stuck spinning
    isLoading = false
  }

  // ✅ one reset, written next to the thing it undoes
  func load() async throws {
    isLoading = true
    defer { isLoading = false }      // runs on return, throw and cancellation
    items = try await api.feed()
  }
}

