// ✅ fix 2: keep the class, add copy-on-write
struct Buffer {
  private final class Storage {
    var bytes: [UInt8] = []
    init() {}
    init(copying other: Storage) { bytes = other.bytes }
  }
  private var storage = Storage()

  mutating func append(_ byte: UInt8) {
    if !isKnownUniquelyReferenced(&storage) {
      storage = Storage(copying: storage)      // clone only when shared
    }
    storage.bytes.append(byte)
  }
}

